#:property AllowUnsafeBlocks=true

Console.WriteLine($"nint size: {nint.Size} bytes");

// stackalloc nint into a Span
Span<nint> signedSpan = stackalloc nint[4];
for (int i = 0; i < signedSpan.Length; i++)
    signedSpan[i] = (nint)(i * 10);

Console.WriteLine("Span<nint>:");
foreach (var v in signedSpan)
    Console.WriteLine($"  {v}");

// stackalloc nuint into a Span
Span<nuint> unsignedSpan = stackalloc nuint[3];
for (int i = 0; i < unsignedSpan.Length; i++)
    unsignedSpan[i] = (nuint)(i * 100);

Console.WriteLine("Span<nuint>:");
foreach (var v in unsignedSpan)
    Console.WriteLine($"  {v}");

Console.WriteLine("Success — stackalloc with nint/nuint works!");

